mapper.select:
SELECT 

WHERE we.workation_id = #{workationId}

ORDER BY we.spent_at DESC, we.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM workation_expenses we
 WHERE we.workation_id = #{workationId}

SELECT 

JOIN workations w
  ON w.id = we.workation_id
 AND w.user_id = #{userId}
WHERE we.id = #{expenseId}

SELECT COUNT(*)
  FROM expense_categories
 WHERE id          = #{expenseCategoryId}
   AND budget_type = #{budgetType}
   AND (user_id IS NULL OR user_id = #{userId})

SELECT card_type
  FROM cards
 WHERE id      = #{cardId}
   AND user_id = #{userId}
   AND (is_deleted = 0 OR is_deleted IS NULL)
